import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {object} NodeConfig
 * @property {string} [imageUrl]
 * @property {any[]} [textContent]
 * @property {any} [intent]
 * @property {Record<string,string>} [colors]
 */

/**
 * @typedef {object} NodeContext
 * @property {any} THREE
 * @property {object} textureLoader
 * @property {function(string):Promise<any>} textureLoader.loadTexture
 * @property {object} fontAtlas
 * @property {function(string,object):any} fontAtlas.createText
 * @property {function(string,any):any} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container – the adapter will position/rotate/scale it later
  const root = new Group();

  // ---------- Textured Plane ----------
  const planeWidth = 1.6; // derived from image aspect 512/320 ≈ 1.6
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  /** @type {any|null} */
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---------- Text Content ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Slightly in front of the plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // ---------- UserData & Cleanup ----------
  root.userData.handlers = {};

  // Keep track of any GSAP timelines we might create in the future
  /** @type {any[]} */
  const timelines = [];

  root.userData.cleanup = () => {
    // Dispose three.js resources
    geometry.dispose();
    material.dispose();
    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }
    // Kill GSAP timelines
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });
    timelines.length = 0;
  };

  return root;
}
